// SPDX-License-Identifier: Apache-2.0
// Self-checking TB of DMA_apb (generated by scripts/apb/gen_apb.py; do not edit).
// Generic part: reset values, ID, scratch and RW registers with byte strobes,
// read-only writes ignored, unmapped and misaligned accesses (PSLVERR),
// back-to-back and idle-separated transfers, reset at the end.
// IP part: task ip_func() from tb/apb/DMA_apb_func.svh drives the core
// through the registers and its protocol pins. The bound checker
// tb/cov/DMA_apb_sva.sv checks every read and every core input on every clock.
`timescale 1ns/1ps
module DMA_apb_tb;
  logic        PCLK = 0, PRESETN = 0, PSEL = 0, PENABLE = 0, PWRITE = 0;
  logic [11:0] PADDR = 0;
  logic [31:0] PWDATA = 0;
  logic [3:0]  PSTRB = 0;
  wire  [31:0] PRDATA;
  wire         PREADY, PSLVERR, irq;
  wire  [3:0]    m_awid;
  wire  [31:0]   m_awaddr;
  wire  [7:0]    m_awlen;
  wire  [2:0]    m_awsize;
  wire  [1:0]    m_awburst;
  wire  [2:0]    m_awprot;
  wire           m_awvalid;
  logic          m_awready;
  wire  [31:0]   m_wdata;
  wire  [3:0]    m_wstrb;
  wire           m_wlast;
  wire           m_wvalid;
  logic          m_wready;
  logic [3:0]    m_bid;
  logic [1:0]    m_bresp;
  logic          m_bvalid;
  wire           m_bready;
  wire  [3:0]    m_arid;
  wire  [31:0]   m_araddr;
  wire  [7:0]    m_arlen;
  wire  [2:0]    m_arsize;
  wire  [1:0]    m_arburst;
  wire  [2:0]    m_arprot;
  wire           m_arvalid;
  logic          m_arready;
  logic [3:0]    m_rid;
  logic [31:0]   m_rdata;
  logic [1:0]    m_rresp;
  logic          m_rlast;
  logic          m_rvalid;
  wire           m_rready;
  DMA_apb dut (.*);
  always #5 PCLK = ~PCLK;

  localparam logic [31:0] ID_VALUE = 32'h5C090100;
  localparam logic [11:0] A_ID = 12'h000;
  localparam logic [11:0] A_IRQ_STATUS = 12'h004;
  localparam logic [11:0] A_IRQ_ENABLE = 12'h008;
  localparam logic [11:0] A_FLAGS = 12'h00C;
  localparam logic [11:0] A_SCRATCH = 12'h010;
  localparam logic [11:0] A_SRC0 = 12'h014;
  localparam logic [11:0] A_DST0 = 12'h018;
  localparam logic [11:0] A_LEN0 = 12'h01C;
  localparam logic [11:0] A_FILL0 = 12'h020;
  localparam logic [11:0] A_SRC1 = 12'h024;
  localparam logic [11:0] A_DST1 = 12'h028;
  localparam logic [11:0] A_LEN1 = 12'h02C;
  localparam logic [11:0] A_FILL1 = 12'h030;
  localparam logic [11:0] A_SRC2 = 12'h034;
  localparam logic [11:0] A_DST2 = 12'h038;
  localparam logic [11:0] A_LEN2 = 12'h03C;
  localparam logic [11:0] A_FILL2 = 12'h040;
  localparam logic [11:0] A_SRC3 = 12'h044;
  localparam logic [11:0] A_DST3 = 12'h048;
  localparam logic [11:0] A_LEN3 = 12'h04C;
  localparam logic [11:0] A_FILL3 = 12'h050;
  localparam logic [11:0] A_MODE = 12'h054;
  localparam logic [11:0] A_CMD = 12'h058;
  localparam logic [11:0] A_STATUS = 12'h05C;
  localparam logic [11:0] A_CHECKSUM = 12'h060;
  localparam logic [11:0] A_CYCLES = 12'h064;
  localparam int IRQ_DONE0 = 0;
  localparam int IRQ_DONE1 = 1;
  localparam int IRQ_DONE2 = 2;
  localparam int IRQ_DONE3 = 3;
  localparam int IRQ_ERR = 4;
  localparam logic [31:0] IRQ_ALL = 32'h1F;

  int errors = 0;
  function automatic void fail(input string m);
    errors++;
    $display("ERROR: %s @%0t", m, $time);
  endfunction
  task automatic cycles(input int n); repeat (n) @(negedge PCLK); endtask

  // one APB transfer; read data and PSLVERR land in rdv / rerr
  logic [31:0] rdv;
  logic        rerr;
  bit          no_idle = 0;   // 1: never insert idle cycles
  task automatic apb(input logic w, input logic [11:0] a, input logic [31:0] d,
                    input logic [3:0] s);
    if (!no_idle) repeat ($urandom % 3) @(negedge PCLK);
    @(negedge PCLK);
    apb_now(w, a, d, s);
  endtask
  // same, setup phase starting at the current negedge (exact access timing)
  task automatic apb_now(input logic w, input logic [11:0] a, input logic [31:0] d,
                        input logic [3:0] s);
    PSEL = 1; PENABLE = 0; PWRITE = w; PADDR = a;
    PWDATA = w ? d : $urandom; PSTRB = w ? s : 4'h0;
    @(negedge PCLK);
    PENABLE = 1;
    #1;
    if (PREADY !== 1'b1) fail("PREADY low in access phase");
    rdv = PRDATA; rerr = PSLVERR;
    @(posedge PCLK);
    #1 PSEL = 0; PENABLE = 0;
  endtask
  task automatic wr(input logic [11:0] a, input logic [31:0] d);
    apb(1, a, d, 4'hF);
    if (rerr) fail($sformatf("PSLVERR on write %h", a));
  endtask
  task automatic wrs(input logic [11:0] a, input logic [31:0] d, input logic [3:0] s);
    apb(1, a, d, s);
    if (rerr) fail($sformatf("PSLVERR on write %h", a));
  endtask
  task automatic rd(input logic [11:0] a);
    apb(0, a, 0, 0);
    if (rerr) fail($sformatf("PSLVERR on read %h", a));
  endtask
  task automatic rd_exp(input logic [11:0] a, input logic [31:0] e);
    rd(a);
    if (rdv !== e) fail($sformatf("read %h = %h, expected %h", a, rdv, e));
  endtask
  // poll until (read & mask) == val, at most n reads
  task automatic poll(input logic [11:0] a, input logic [31:0] mask, input logic [31:0] val,
                     input int n);
    int k;
    k = 0;
    rd(a);
    while ((rdv & mask) != val && k < n) begin rd(a); k++; end
    if ((rdv & mask) != val) fail($sformatf("poll %h timed out (%h)", a, rdv));
  endtask
  task automatic bad(input logic w, input logic [11:0] a);
    apb(w, a, $urandom, 4'hF);
    if (!rerr) fail($sformatf("no PSLVERR at %h", a));
    if (!w && rdv !== 0) fail($sformatf("unmapped read %h returned %h", a, rdv));
  endtask
  function automatic logic [31:0] merge(input logic [31:0] o, input logic [31:0] n,
                                        input logic [3:0] s);
    for (int b = 0; b < 4; b++) if (s[b]) o[8*b +: 8] = n[8*b +: 8];
    return o;
  endfunction
  // RW register: ones, zeros, random byte strobes; restores rst afterwards
  task automatic rw_test(input logic [11:0] a, input logic [31:0] m, input logic [31:0] rst);
    logic [31:0] v, d;
    logic [3:0]  s;
    wr(a, 32'hFFFF_FFFF); rd_exp(a, m);
    wr(a, 32'h0);         rd_exp(a, 0);
    v = 0;
    for (int i = 0; i < 16; i++) begin
      d = $urandom; s = i[3:0];
      wrs(a, d, s); v = merge(v, d, s) & m;
      rd_exp(a, v);
    end
    wr(a, rst); rd_exp(a, rst);
  endtask

  `include "apb/DMA_apb_func.svh"

  task automatic check_reset_values;
    rd_exp(A_ID, ID_VALUE);
    rd_exp(A_IRQ_ENABLE, 0);
    rd_exp(A_SCRATCH, 0);
    rd_exp(A_SRC0, 32'h0);
    rd_exp(A_DST0, 32'h0);
    rd_exp(A_LEN0, 32'h0);
    rd_exp(A_FILL0, 32'h0);
    rd_exp(A_SRC1, 32'h0);
    rd_exp(A_DST1, 32'h0);
    rd_exp(A_LEN1, 32'h0);
    rd_exp(A_FILL1, 32'h0);
    rd_exp(A_SRC2, 32'h0);
    rd_exp(A_DST2, 32'h0);
    rd_exp(A_LEN2, 32'h0);
    rd_exp(A_FILL2, 32'h0);
    rd_exp(A_SRC3, 32'h0);
    rd_exp(A_DST3, 32'h0);
    rd_exp(A_LEN3, 32'h0);
    rd_exp(A_FILL3, 32'h0);
    rd_exp(A_MODE, 32'h0);
    rd_exp(A_CMD, 0);                             // write-only: reads 0
  endtask

  task automatic reg_tests;
    check_reset_values();
    wr(A_ID, ~ID_VALUE); rd_exp(A_ID, ID_VALUE);          // read-only: ignored
    wr(A_FLAGS, 32'hFFFF_FFFF);
    rw_test(A_SCRATCH, 32'hFFFF_FFFF, 0);
    rw_test(A_IRQ_ENABLE, IRQ_ALL, 0);
    rw_test(A_SRC0, 32'hFFFFFFFF, 32'h0);
    rw_test(A_DST0, 32'hFFFFFFFF, 32'h0);
    rw_test(A_LEN0, 32'hFFFF, 32'h0);
    rw_test(A_FILL0, 32'hFFFFFFFF, 32'h0);
    rw_test(A_SRC1, 32'hFFFFFFFF, 32'h0);
    rw_test(A_DST1, 32'hFFFFFFFF, 32'h0);
    rw_test(A_LEN1, 32'hFFFF, 32'h0);
    rw_test(A_FILL1, 32'hFFFFFFFF, 32'h0);
    rw_test(A_SRC2, 32'hFFFFFFFF, 32'h0);
    rw_test(A_DST2, 32'hFFFFFFFF, 32'h0);
    rw_test(A_LEN2, 32'hFFFF, 32'h0);
    rw_test(A_FILL2, 32'hFFFFFFFF, 32'h0);
    rw_test(A_SRC3, 32'hFFFFFFFF, 32'h0);
    rw_test(A_DST3, 32'hFFFFFFFF, 32'h0);
    rw_test(A_LEN3, 32'hFFFF, 32'h0);
    rw_test(A_FILL3, 32'hFFFFFFFF, 32'h0);
    rw_test(A_MODE, 32'hF, 32'h0);
    wr(A_STATUS, 32'hFFFF_FFFF);                     // read-only: ignored
    wr(A_CHECKSUM, 32'hFFFF_FFFF);                     // read-only: ignored
    wr(A_CYCLES, 32'hFFFF_FFFF);                     // read-only: ignored
    // unmapped and misaligned: PSLVERR, read data 0, no side effects
    wr(A_SCRATCH, 32'h5A5A_A5A5);
    bad(0, 12'h001); bad(1, 12'h001);
    bad(0, 12'h002); bad(1, 12'h002);
    bad(0, 12'h003); bad(1, 12'h003);
    bad(0, 12'h011); bad(1, 12'h011);
    bad(0, 12'h013); bad(1, 12'h013);
    bad(0, 12'h068); bad(1, 12'h068);
    bad(0, 12'h080); bad(1, 12'h080);
    bad(0, 12'h100); bad(1, 12'h100);
    bad(0, 12'h200); bad(1, 12'h200);
    bad(0, 12'h400); bad(1, 12'h400);
    bad(0, 12'h800); bad(1, 12'h800);
    bad(0, 12'hFFC); bad(1, 12'hFFC);
    rd_exp(A_SCRATCH, 32'h5A5A_A5A5);
    no_idle = 1;                                            // back-to-back
    for (int i = 0; i < 4; i++) begin wr(A_SCRATCH, i); rd_exp(A_SCRATCH, i); end
    no_idle = 0;
    wr(A_SCRATCH, 0);
    wr(A_IRQ_STATUS, IRQ_ALL);
  endtask

  initial begin
    cycles(3);
    PRESETN = 1;
    cycles(2);
    reg_tests();
    ip_func();
    PRESETN = 0;
    cycles(3);
    if (irq !== 0 || PRDATA !== 0) fail("outputs in reset");
    PRESETN = 1;
    cycles(2);
    check_reset_values();
    rd_exp(A_IRQ_STATUS, 0);
    if (errors == 0) $display("TEST PASSED: DMA_apb");
    else $display("TEST FAILED: DMA_apb (%0d errors)", errors);
    $finish;
  end

  initial begin
    #20ms;
    $display("TEST FAILED: DMA_apb (timeout)");
    $finish;
  end
endmodule
